class P:
    pass

p = P()

try:
    print(p.nope)
except AttributeError:
    print("attr ok")

try:
    print(int("abc"))
except ValueError:
    print("value ok")

try:
    a, b = [1]
except ValueError:
    print("unpack ok")

try:
    x = 5
    x()
except TypeError:
    print("call ok")

try:
    print(len(5))
except TypeError:
    print("len ok")

s = "abc"
try:
    s[0] = "z"
except TypeError:
    print("caught")

s = {1, 2}
try:
    s[0] = 1
except TypeError:
    print("caught")

xs = [1]

def add() -> int:
    xs.append(2)
    return len(xs)

print(add(), xs)
